INSERT INTO accommodation_properties (name, slug, tier, property_type, short_description, full_description, county, locality, price_from_kes, price_note, distance_note, cancellation_note, payment_note, included_note, badge_label, amenities, highlights, booking_url, disclosure, image_url, image_alt, image_credit, status, is_featured, display_order)
VALUES
 ('Diani Backpackers','diani-backpackers','budget','hostel','Barefoot hostel two minutes from Diani Beach.','Private and dorm rooms, outdoor kitchen, surf storage and a shaded courtyard built for travellers who would rather spend on experiences than pillows.','Kwale','Diani Beach',2500,'per dorm bed','2 min walk to the beach','Free cancellation up to 48 hours','Pay on arrival','Breakfast included','Gen Z pick',ARRAY['wifi','breakfast','surf storage','shared kitchen'],ARRAY['Beach 2 min','Surf lessons onsite','Weekly bonfire'],'https://example.com/stays/diani-backpackers','Internal test listing','marketplace/stays/diani-backpackers.jpg','Diani Beach','Wikimedia Commons / CC BY-SA 4.0','published',true,10),
 ('Mara Eco Camp','mara-eco-camp','budget','camp','Solar-powered tented camp on the edge of the Maasai Mara.','Tented rooms with bucket showers, a communal fire and guided dawn drives. Rates are per person sharing and include conservancy fees.','Narok','Maasai Mara',6500,'per person sharing','15 min to the Oloololo gate','Free cancellation up to 7 days','Deposit 20%','Breakfast and dinner included','Gen Z pick',ARRAY['solar power','guided drives','communal fire','meals'],ARRAY['Big Five territory','Community-owned conservancy','Dawn game drives'],'https://example.com/stays/mara-eco-camp','Internal test listing','marketplace/stays/mara-eco-camp.jpg','Maasai Mara landscape','Wikimedia Commons / CC BY-SA 4.0','published',true,20),
 ('Nairobi Social Hostel','nairobi-social-hostel','budget','hostel','City hostel with co-working, rooftop suppers and easy matatu access.','Mixed and female dorms, fast wifi, a rooftop kitchen and walking-distance access to the CBD, museums and night markets.','Nairobi','Kilimani',3000,'per dorm bed','10 min to the CBD','Free cancellation up to 24 hours','Pay on arrival','Breakfast included','City base',ARRAY['wifi','co-working','rooftop','laundry'],ARRAY['Rooftop suppers','Co-working desks','Walk to museums'],'https://example.com/stays/nairobi-social-hostel','Internal test listing','marketplace/stays/nairobi-social-hostel.jpg','Nairobi skyline','Wikimedia Commons / CC BY-SA 4.0','published',false,30)
INSERT INTO partner_businesses (name, slug, category, tagline, short_description, full_description, county, locality, service_area, redirect_url, redirect_label, disclosure, image_url, image_alt, image_credit, status, is_featured, display_order)
VALUES
 ('Mara Safari Collective','mara-safari-collective','experiences','Community guides, dawn drives','Guided game drives and walking safaris run by Mara-born guides.','Small-group drives, birding walks and conservancy visits. Book directly with the collective; YTCI receives no commission.','Narok','Maasai Mara','Maasai Mara and conservancies','https://example.com/partners/mara-safari-collective','Book a guide','Direct partner link','marketplace/partners/mara-safari-collective.jpg','Maasai Mara','Wikimedia Commons / CC BY-SA 4.0','published',true,10),
 ('Tamu Kenyan Kitchen','tamu-kenyan-kitchen','food_drink','Home-style Kenyan plates','A neighbourhood kitchen serving ugali, sukuma and slow-cooked stews.','Lunch and early dinner, vegetarian options daily, and a market tour on Saturdays.','Nairobi','Westlands','Nairobi','https://example.com/partners/tamu-kenyan-kitchen','See the menu','Direct partner link','marketplace/partners/tamu-kenyan-kitchen.jpg','Kenyan food','Wikimedia Commons / CC BY-SA 4.0','published',false,20),
 ('Nairobi City Transfers','nairobi-city-transfers','transport','Airport and city rides','Pre-booked airport transfers and day-hire cars with vetted drivers.','Fixed fares to the CBD, Karen and the airport. Meet-and-greet included.','Nairobi','Embakasi','Nairobi','https://example.com/partners/nairobi-city-transfers','Book a transfer','Direct partner link','marketplace/partners/nairobi-city-transfers.jpg','Nairobi','Wikimedia Commons / CC BY-SA 4.0','published',false,30)
